def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Early game: establish cooperation, but punish persistent defection.
    if n < 10:
        if opp_c == 0:
            return 'D'
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'

    recent = history[-10:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_opp_c = len(recent) - recent_opp_d

    # Clear recent trends.
    if recent_opp_d >= 8:
        return 'D'
    if recent_opp_c >= 9:
        return 'C'

    # Overall cooperation levels.
    if opp_rate >= 0.8:
        return 'C'
    if opp_rate <= 0.3:
        return 'D'

    # Forgive isolated defections when opponent is generally cooperative,
    # but retaliate if they have been defecting frequently recently.
    if my_last == 'C' and opp_last == 'D':
        if opp_rate > 0.6 and recent_opp_d <= 5:
            return 'C'
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        return 'C'

    # Mutual defection: try to reset if the opponent is still mostly cooperative.
    if my_last == 'D' and opp_last == 'D':
        if opp_rate > 0.6 and recent_opp_d <= 5:
            return 'C'
        return 'D'

    # Mutual cooperation.
    if my_last == 'C' and opp_last == 'C':
        return 'C'

    if opp_rate > 0.5:
        return 'C'
    return 'D'
